<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { BookOpen,FilePlus2,Pencil,RefreshCw,Search,Sparkles,ThumbsUp,Trash2,X } from 'lucide-vue-next'
import { useAuthStore } from '@/stores/useAuthStore'
type KnowledgeRef={type:string;id:string;name:string;status?:string}
type Knowledge={id:string;title:string;category:string;summary:string;content:string;tags:string[];helpful:number;views:number;status:string;source:string;sourceId?:string;author:string;createdAt:string;updatedAt:string;related:KnowledgeRef[]}
type AnalysisOption={id:string;title:string;rootCause:string;createdAt:string}
type Option={id:string;name:string;status?:string}
const auth=useAuthStore();const items=ref<Knowledge[]>([]);const analyses=ref<AnalysisOption[]>([]);const query=ref('');const statusFilter=ref('all');const selected=ref<Knowledge|null>(null);const showEditor=ref(false);const editing=ref(false);const selectedAnalysis=ref('');const loading=ref(false);const saving=ref(false);const message=ref('');const error=ref('')
const form=reactive({id:'',title:'',category:'',summary:'',content:'',tags:'',status:'draft'})
const assets=ref<Option[]>([]);const tickets=ref<Option[]>([]);const alerts=ref<Option[]>([]);const assetIds=ref<string[]>([]);const ticketIds=ref<string[]>([]);const alertIds=ref<string[]>([])
const canManage=computed(()=>Boolean(auth.user?.permissions.includes('aiops:execute')))
const visibleItems=computed(()=>statusFilter.value==='all'?items.value:items.value.filter(item=>item.status===statusFilter.value))
const headers=()=>({Authorization:`Bearer ${auth.token}`,'Content-Type':'application/json'})
async function request<T>(path:string,init?:RequestInit):Promise<T>{const response=await fetch(path,{...init,headers:headers()});if(response.status===204)return undefined as T;const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error((data as {message?:string}).message||'知识库请求失败');return data as T}
async function loadOptions(){try{const [assetData,ticketData,alertData]=await Promise.all([request<any>('/api/v1/cmdb/assets?pageSize=200'),request<any>('/api/v1/tickets'),request<any>('/api/v1/monitor/alerts?pageSize=200')]);const assetItems=Array.isArray(assetData)?assetData:assetData.data||[];const ticketItems=Array.isArray(ticketData)?ticketData:ticketData.items||ticketData.data||[];const alertItems=Array.isArray(alertData)?alertData:alertData.items||alertData.data||[];assets.value=assetItems.map((item:any)=>({id:item.id,name:item.name||item.id,status:item.status}));tickets.value=ticketItems.map((item:any)=>({id:item.id,name:item.title||item.name||item.id,status:item.status}));alerts.value=alertItems.map((item:any)=>({id:item.id,name:item.title||item.name||item.id,status:item.status}))}catch{}}
async function load(){loading.value=true;error.value='';try{const suffix=canManage.value?'?all=1&q=':'?q=';items.value=await request<Knowledge[]>('/api/v1/aiops/knowledge'+suffix+encodeURIComponent(query.value));if(selected.value)selected.value=items.value.find(item=>item.id===selected.value?.id)||null;if(canManage.value){await loadOptions();if(!analyses.value.length)analyses.value=await request<AnalysisOption[]>('/api/v1/aiops/analyses')}}catch(reason){error.value=reason instanceof Error?reason.message:'知识库加载失败'}finally{loading.value=false}}
function resetForm(){Object.assign(form,{id:'',title:'',category:'故障处理',summary:'',content:'',tags:'',status:'draft'});assetIds.value=[];ticketIds.value=[];alertIds.value=[];editing.value=false}
function create(){resetForm();showEditor.value=true;message.value='';error.value=''}
function edit(item:Knowledge){Object.assign(form,{id:item.id,title:item.title,category:item.category,summary:item.summary,content:item.content,tags:item.tags.join(','),status:item.status});assetIds.value=(item.related||[]).filter(ref=>ref.type==='asset').map(ref=>ref.id);ticketIds.value=(item.related||[]).filter(ref=>ref.type==='ticket').map(ref=>ref.id);alertIds.value=(item.related||[]).filter(ref=>ref.type==='alert').map(ref=>ref.id);editing.value=true;showEditor.value=true;selected.value=item}
function closeEditor(){showEditor.value=false;resetForm()}
async function save(){saving.value=true;error.value='';message.value='';const payload={title:form.title,category:form.category,summary:form.summary,content:form.content,tags:form.tags.split(',').map(value=>value.trim()).filter(Boolean),status:form.status,related:[...assetIds.value.map(id=>({type:'asset',id})),...ticketIds.value.map(id=>({type:'ticket',id})),...alertIds.value.map(id=>({type:'alert',id}))]};try{const item=editing.value?await request<Knowledge>('/api/v1/aiops/knowledge/'+form.id,{method:'PUT',body:JSON.stringify(payload)}):await request<Knowledge>('/api/v1/aiops/knowledge',{method:'POST',body:JSON.stringify(payload)});message.value=editing.value?'知识条目已更新':'知识条目已创建';selected.value=item;closeEditor();await load()}catch(reason){error.value=reason instanceof Error?reason.message:'保存失败'}finally{saving.value=false}}
async function view(item:Knowledge){try{selected.value=await request<Knowledge>('/api/v1/aiops/knowledge/'+item.id);const index=items.value.findIndex(value=>value.id===item.id);if(index>=0)items.value[index]=selected.value}catch(reason){error.value=reason instanceof Error?reason.message:'详情加载失败'}}
async function helpful(item:Knowledge){try{const updated=await request<Knowledge>('/api/v1/aiops/knowledge/'+item.id+'/helpful',{method:'POST'});const index=items.value.findIndex(value=>value.id===item.id);if(index>=0)items.value[index]=updated;if(selected.value?.id===item.id)selected.value=updated}catch(reason){error.value=reason instanceof Error?reason.message:'操作失败'}}
async function remove(item:Knowledge){if(!confirm(`确认删除知识条目“${item.title}”？`))return;try{await request<void>('/api/v1/aiops/knowledge/'+item.id,{method:'DELETE'});if(selected.value?.id===item.id)selected.value=null;message.value='知识条目已删除';await load()}catch(reason){error.value=reason instanceof Error?reason.message:'删除失败'}}
async function synthesize(){if(!selectedAnalysis.value)return;saving.value=true;error.value='';message.value='';try{const item=await request<Knowledge>('/api/v1/aiops/knowledge/synthesize',{method:'POST',body:JSON.stringify({analysisId:selectedAnalysis.value})});message.value='已从分析生成草稿，请完善后发布';selected.value=item;edit(item);await load()}catch(reason){error.value=reason instanceof Error?reason.message:'沉淀失败'}finally{saving.value=false}}
onMounted(load)
</script>

<template>
  <section class="knowledge-panel">
    <header class="knowledge-toolbar"><div><span>KNOWLEDGE CENTER</span><h2>运维知识库</h2><p>沉淀故障案例、排查步骤、复盘结论和可复用 Runbook。</p></div><div><button v-if="canManage" class="primary" @click="create"><FilePlus2/>新建知识</button><button :disabled="loading" @click="load"><RefreshCw :class="{spin:loading}"/>刷新</button></div></header>
    <div class="knowledge-search"><label><Search/><input v-model="query" placeholder="搜索标题、正文、分类或标签" @keyup.enter="load"></label><select v-model="statusFilter"><option value="all">全部状态</option><option value="published">已发布</option><option value="draft">草稿</option></select><button @click="load">检索</button></div>
    <div v-if="canManage && analyses.length" class="knowledge-synthesis"><Sparkles/><span>从最近分析沉淀</span><select v-model="selectedAnalysis"><option value="">选择分析记录</option><option v-for="item in analyses" :key="item.id" :value="item.id">{{item.title}} · {{item.rootCause||'待确认'}}</option></select><button :disabled="!selectedAnalysis||saving" @click="synthesize">生成草稿</button></div>
    <p v-if="error" class="knowledge-error">{{error}}</p><p v-if="message" class="knowledge-message">{{message}}</p>
    <div class="knowledge-layout">
      <div class="knowledge-list"><article v-for="item in visibleItems" :key="item.id" :class="{active:selected?.id===item.id}" @click="view(item)"><header><b>{{item.category||'未分类'}}</b><span :class="item.status">{{item.status==='published'?'已发布':'草稿'}}</span></header><h3>{{item.title}}</h3><p>{{item.summary}}</p><div class="knowledge-tags"><span v-for="tag in item.tags" :key="tag">{{tag}}</span></div><footer><span><ThumbsUp/>{{item.helpful}}</span><span>{{item.views}} 次浏览</span><span>{{item.updatedAt}}</span></footer></article><div v-if="!visibleItems.length" class="knowledge-empty"><BookOpen/><strong>没有匹配的知识条目</strong><span>调整关键词或新建一条知识。</span></div></div>
      <aside v-if="selected" class="knowledge-detail"><header><div><span>{{selected.category||'未分类'}} · {{selected.status==='published'?'已发布':'草稿'}}</span><h3>{{selected.title}}</h3><p>{{selected.summary}}</p></div><button @click="selected=null"><X/></button></header><div class="knowledge-meta"><span>作者 {{selected.author||'未知'}}</span><span>更新 {{selected.updatedAt}}</span><span v-if="selected.sourceId">来源 {{selected.sourceId}}</span></div><div class="knowledge-content">{{selected.content}}</div><div class="knowledge-tags"><span v-for="tag in selected.tags" :key="tag">{{tag}}</span></div><div v-if="selected.related?.length" class="knowledge-related"><b>关联对象</b><div><span v-for="ref in selected.related" :key="ref.type+ref.id">{{ref.type==='asset'?'资产':ref.type==='ticket'?'工单':'告警'}} · {{ref.name||ref.id}}</span></div></div><footer><button @click="helpful(selected)"><ThumbsUp/>有帮助</button><button v-if="canManage" @click="edit(selected)"><Pencil/>编辑</button><button v-if="canManage" class="danger" @click="remove(selected)"><Trash2/>删除</button></footer></aside>
    </div>
    <div v-if="showEditor" class="knowledge-editor"><form @submit.prevent="save"><header><div><span>{{editing?'EDIT KNOWLEDGE':'NEW KNOWLEDGE'}}</span><h3>{{editing?'编辑知识条目':'新建知识条目'}}</h3></div><button type="button" @click="closeEditor"><X/></button></header><div class="knowledge-form-grid"><label>标题<input v-model="form.title" required></label><label>分类<input v-model="form.category" required></label><label>状态<select v-model="form.status"><option value="draft">草稿</option><option value="published">发布</option></select></label><label>标签<input v-model="form.tags" placeholder="用英文逗号分隔"></label><label class="wide">关联资产<select v-model="assetIds" multiple><option v-for="item in assets" :key="item.id" :value="item.id">{{item.name}} · {{item.status||''}}</option></select></label><label class="wide">关联工单<select v-model="ticketIds" multiple><option v-for="item in tickets" :key="item.id" :value="item.id">{{item.name}} · {{item.status||''}}</option></select></label><label class="wide">关联告警<select v-model="alertIds" multiple><option v-for="item in alerts" :key="item.id" :value="item.id">{{item.name}} · {{item.status||''}}</option></select></label><label class="wide">摘要<textarea v-model="form.summary" required></textarea></label><label class="wide">正文<textarea v-model="form.content" required></textarea></label></div><footer><button type="button" @click="closeEditor">取消</button><button class="primary" type="submit" :disabled="saving">{{saving?'保存中':'保存'}}</button></footer></form></div>
  </section>
</template>

<style scoped>
.knowledge-panel{color:#dcecff}.knowledge-toolbar{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.knowledge-toolbar span{color:#2ad1e7;font-size:10px;letter-spacing:.16em}.knowledge-toolbar h2{margin:5px 0}.knowledge-toolbar p{margin:0;color:#718ba2;font-size:12px}.knowledge-toolbar>div:last-child{display:flex;gap:8px}.knowledge-panel button{display:inline-flex;align-items:center;gap:6px;padding:8px 11px;border:1px solid #21445d;background:#0b263b;color:#bdd8e9;cursor:pointer}.knowledge-panel button.primary{background:#087c9e}.knowledge-panel button.danger{border-color:#783e49;color:#ff9aa7}.knowledge-panel button svg{width:14px}.knowledge-search{display:flex;gap:8px;margin:16px 0}.knowledge-search label{display:flex;align-items:center;flex:1;border:1px solid #21445d;background:#071b2c;padding:0 10px}.knowledge-search label svg{color:#2ad1e7;width:15px}.knowledge-search input{width:100%;height:38px;border:0;outline:0;background:transparent;color:#dcecff}.knowledge-search select,.knowledge-synthesis select{height:38px;border:1px solid #21445d;background:#071b2c;color:#bdd8e9;padding:0 9px}.knowledge-synthesis{display:flex;align-items:center;gap:9px;padding:10px 12px;border:1px solid #1b4b62;background:#0a273b;color:#8fb3c7;font-size:12px}.knowledge-synthesis svg{width:15px;color:#2ad1e7}.knowledge-synthesis select{flex:1}.knowledge-layout{display:grid;grid-template-columns:minmax(360px,1fr) minmax(420px,.9fr);gap:14px;margin-top:14px}.knowledge-list{display:grid;align-content:start;gap:9px;max-height:620px;overflow:auto}.knowledge-list article{padding:14px;border:1px solid #173b55;background:#0a263a;cursor:pointer}.knowledge-list article.active{border-color:#23bed8}.knowledge-list article header,.knowledge-list article footer{display:flex;justify-content:space-between;align-items:center}.knowledge-list article header b{color:#27cfe5;font-size:10px}.knowledge-list article header span{padding:3px 6px;background:#26303b;color:#94a3b8;font-size:10px}.knowledge-list article header span.published{background:#0b3a3b;color:#5eead4}.knowledge-list h3{margin:9px 0 6px;font-size:15px}.knowledge-list p{margin:0;color:#7891a4;font-size:12px;line-height:1.6}.knowledge-list footer{margin-top:10px;color:#5f7b90;font-size:10px}.knowledge-tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:9px}.knowledge-tags span{padding:3px 6px;background:#10334a;color:#7fb1c5;font-size:10px}.knowledge-detail{padding:17px;border:1px solid #1b4b62;background:#071d2f;min-height:420px}.knowledge-detail>header{display:flex;justify-content:space-between;gap:10px}.knowledge-detail header span{color:#27cfe5;font-size:10px}.knowledge-detail h3{margin:7px 0}.knowledge-detail header p{margin:0;color:#7891a4;font-size:12px}.knowledge-meta{display:flex;flex-wrap:wrap;gap:8px 14px;margin:13px 0;padding:9px 0;border-top:1px solid #15354d;border-bottom:1px solid #15354d;color:#617e92;font-size:10px}.knowledge-content{white-space:pre-wrap;color:#a9c0cf;line-height:1.75;font-size:13px}.knowledge-detail footer{display:flex;gap:8px;margin-top:18px}.knowledge-empty{display:grid;place-items:center;gap:7px;min-height:260px;color:#5f7b91;text-align:center}.knowledge-empty svg{width:28px;color:#2ad1e7}.knowledge-empty span{font-size:11px}.knowledge-error,.knowledge-message{margin:10px 0;padding:9px 11px;font-size:12px}.knowledge-error{border:1px solid #783e49;background:#35161e;color:#ff9aa7}.knowledge-message{border:1px solid #155e75;background:#082b38;color:#a5f3fc}.knowledge-editor{position:fixed;inset:0;z-index:50;display:grid;place-items:center;padding:28px;background:rgba(2,8,14,.78)}.knowledge-editor form{width:min(880px,100%);max-height:90vh;overflow:auto;border:1px solid #246c98;background:#071925}.knowledge-editor header{display:flex;justify-content:space-between;padding:16px 18px;border-bottom:1px solid #173b55}.knowledge-editor header span{color:#2ad1e7;font-size:10px}.knowledge-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:18px}.knowledge-form-grid label{display:grid;gap:6px;color:#7894a8;font-size:11px}.knowledge-form-grid label.wide{grid-column:1/-1}.knowledge-form-grid input,.knowledge-form-grid select,.knowledge-form-grid textarea{border:1px solid #22465f;background:#061725;color:#dcecff;padding:9px;outline:none}.knowledge-form-grid textarea{min-height:76px;resize:vertical}.knowledge-editor footer{display:flex;justify-content:flex-end;gap:8px;padding:14px 18px;border-top:1px solid #173b55}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:1000px){.knowledge-layout{grid-template-columns:1fr}.knowledge-synthesis{align-items:stretch;flex-wrap:wrap}.knowledge-synthesis select{min-width:260px}.knowledge-form-grid{grid-template-columns:1fr}}
.knowledge-form-grid select[multiple]{min-height:88px}.knowledge-related{margin-top:12px;padding:10px;border:1px solid #15354d;background:#061620}.knowledge-related>b{display:block;margin-bottom:7px;color:#6f91a5;font-size:10px}.knowledge-related>div{display:flex;flex-wrap:wrap;gap:6px}.knowledge-related span{padding:4px 7px;background:#10334a;color:#8fc6d8;font-size:10px}
</style>
